{
  "mechanisms": [
    {
      "name": "choice_perseveration",
      "title": "Choice perseveration",
      "description": "Adds an additive bias to the RL Q-value of the last action taken in the current state.",
      "params": [
        {
          "name": "stay_bias",
          "bounds": [-10, 10]
        }
      ],
      "evidence": "if last_action[s] >= 0:\n                Q_s[last_action[s]] += stay_bias",
      "expressible_in_slots": true
    },
    {
      "name": "wm_delta_learning",
      "title": "WM delta learning",
      "description": "Working memory updates its values via a delta rule toward a target distribution, rather than instantaneous perfect encoding.",
      "params": [
        {
          "name": "wm_lr",
          "bounds": [0, 1]
        }
      ],
      "evidence": "w[s, :] = (1.0 - wm_lr) * w[s, :] + wm_lr * target",
      "expressible_in_slots": true
    },
    {
      "name": "load_dependent_wm_confusion",
      "title": "Load-dependent WM confusion",
      "description": "The working memory target distribution for rewarded trials assigns a probability to the chosen action that decreases with set size, spreading the remaining probability uniformly across unchosen actions.",
      "params": [
        {
          "name": "confusion_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "conf_eff = 1.0 - (1.0 - np.clip(confusion_rate, 0.0, 1.0)) ** max(1, nS)",
      "expressible_in_slots": true
    },
    {
      "name": "wm_forgetting_on_error",
      "title": "WM forgetting on error",
      "description": "On unrewarded trials, working memory targets a uniform distribution, effectively forgetting the current state-action association.",
      "params": [],
      "evidence": "else:\n                target = w_0[s, :].copy()  # forget toward uniform",
      "expressible_in_slots": true
    }
  ]
}
